import { createContext, ReactNode, useEffect, useState } from 'react';

export interface AuthContextType {
    token: string | null;
    isAuthenticated: boolean;
    login: (token: string) => void;
    logout: () => void;
}

export const AuthContext = createContext<AuthContextType | null>(null)

export const AuthProvider = ({children}: {children : ReactNode}) => {
    const [token, setToken] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const storedToken = localStorage.getItem("token");
        if(storedToken){
            setToken(storedToken);
        }
        setIsLoading(false);
    }, []);

    if (isLoading) {
        return null;
    }

    const isAuthenticated = !!token;

    const login = (newToken: string) => {
        setToken(newToken);
        localStorage.setItem("token", newToken);
    };

    const logout = () => {
        setToken(null);
        localStorage.removeItem("token");
    }

    return (
        <AuthContext.Provider value={{token, isAuthenticated, login, logout}}>
            {children}
        </AuthContext.Provider>
    )
}

import { createContext, ReactNode, useEffect, useState } from 'react';

export interface AuthContextType {
    token: string | null;
    isAuthenticated: boolean;
    login: (token: string) => void;
    logout: () => void;
}

export const AuthContext = createContext<AuthContextType | null>(null)

/**
 * Vérifie qu'un token JWT n'est pas expiré (lecture du claim `exp`).
 * Renvoie true si le token ne peut pas être décodé (on ne bloque pas inutilement).
 */
const isTokenValid = (token: string): boolean => {
    try {
        const payload = JSON.parse(atob(token.split(".")[1]));
        if (payload?.exp) {
            return payload.exp * 1000 > Date.now();
        }
        return true;
    } catch {
        return true;
    }
};

export const AuthProvider = ({children}: {children : ReactNode}) => {
    const [token, setToken] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const storedToken = localStorage.getItem("token");
        if (storedToken && isTokenValid(storedToken)) {
            setToken(storedToken);
        } else if (storedToken) {
            // Token présent mais expiré/invalide → on nettoie
            localStorage.removeItem("token");
        }
        setIsLoading(false);
    }, []);

    if (isLoading) {
        return null;
    }

    const isAuthenticated = !!token;

    const login = (newToken: string) => {
        setToken(newToken);
        localStorage.setItem("token", newToken);
    };

    const logout = () => {
        setToken(null);
        localStorage.removeItem("token");
    }

    return (
        <AuthContext.Provider value={{token, isAuthenticated, login, logout}}>
            {children}
        </AuthContext.Provider>
    )
}

"use client";

import { PlusCircle } from "lucide-react";

interface FileButtonProps {
    value: File | null;
    onChange: (file: File | null) => void;
    placeholder?: string;
}

export default function FileButton({
    value,
    onChange,
    placeholder = "Ajouter une photo",
}: FileButtonProps) {
    return (
        <label className="btn-dark">
            <input
                type="file"
                name="fichier"
                accept="image/*"
                onChange={(e) => onChange(e.target.files?.[0] || null)}
                style={{ display: "none" }}
            />
            <span>{value ? value.name : placeholder}</span>
            <PlusCircle size={20} />
        </label>
    );
}

"use client";

import { PlusCircle } from "lucide-react";
import { useState } from "react";

interface FileButtonProps {
    value: File | null;
    onChange: (file: File | null) => void;
    placeholder?: string;
}

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5 Mo

export default function FileButton({
    value,
    onChange,
    placeholder = "Ajouter une photo",
}: FileButtonProps) {
    const [error, setError] = useState<string | null>(null);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setError(null);
        const file = e.target.files?.[0] || null;

        if (!file) {
            onChange(null);
            return;
        }

        if (!file.type.startsWith("image/")) {
            setError("Le fichier doit être une image.");
            e.target.value = "";
            onChange(null);
            return;
        }

        if (file.size > MAX_FILE_SIZE) {
            setError("L'image ne doit pas dépasser 5 Mo.");
            e.target.value = "";
            onChange(null);
            return;
        }

        onChange(file);
    };

    return (
        <div className="file-button-wrapper">
            <label className="btn-dark">
                <input
                    type="file"
                    name="fichier"
                    accept="image/*"
                    onChange={handleChange}
                    style={{ display: "none" }}
                />
                <span>{value ? value.name : placeholder}</span>
                <PlusCircle size={20} />
            </label>
            {error && <p className="error-message">{error}</p>}
        </div>
    );
}

