import { ApiError, FieldError } from "@/types/api.types";

export const API_CONFIG = {
    baseUrl: process.env.NEXT_PUBLIC_URL_API,
    headers: {
        "Content-Type": "application/json",
    },
    timeout: 10000,
};

/**
 * Construit l'URL complète d'un endpoint à partir de la base commune.
 */
export const apiUrl = (endpoint: string) => `${API_CONFIG.baseUrl}${endpoint}`;

/**
 * Construit les headers d'authentification.
 * @param withJson ajoute le header Content-Type: application/json (à désactiver pour du FormData)
 */
export const authHeaders = (token: string, withJson = true): Record<string, string> => ({
    ...(withJson ? API_CONFIG.headers : {}),
    Authorization: `Bearer ${token}`,
});

/**
 * Normalise et lève une erreur API cohérente (status + errors éventuels).
 */
export const buildApiError = async (response: Response): Promise<never> => {
    const data = await response.json().catch(() => ({}));
    const message = Array.isArray(data.errors)
        ? data.errors.map((e: FieldError) => e.message).join("\n")
        : data.message || data.error || `Erreur ${response.status}`;

    const error = new Error(message) as ApiError;
    error.status = response.status;
    if (data.errors) error.errors = data.errors;
    throw error;
};

export const apiFetch = async (endpoint: string, options?: RequestInit) => {
    const response = await fetch(`${API_CONFIG.baseUrl}${endpoint}`, {
        ...options,
        headers: {
            ...API_CONFIG.headers,
            ...options?.headers,
        },
    });

    if (!response.ok) throw new Error(`Erreur API: ${response.status}`);
    return response.json();
};

import { ApiError, FieldError } from "@/types/api.types";

export const API_CONFIG = {
    baseUrl: process.env.NEXT_PUBLIC_URL_API,
    headers: {
        "Content-Type": "application/json",
    },
    timeout: 10000,
};

/**
 * Construit l'URL complète d'un endpoint à partir de la base commune.
 */
export const apiUrl = (endpoint: string) => `${API_CONFIG.baseUrl}${endpoint}`;

/**
 * Construit les headers d'authentification.
 * @param withJson ajoute le header Content-Type: application/json (à désactiver pour du FormData)
 */
export const authHeaders = (token: string, withJson = true): Record<string, string> => ({
    ...(withJson ? API_CONFIG.headers : {}),
    Authorization: `Bearer ${token}`,
});

/**
 * Normalise et lève une erreur API cohérente (status + errors éventuels).
 */
export const buildApiError = async (response: Response): Promise<never> => {
    const data = await response.json().catch(() => ({}));
    const message = Array.isArray(data.errors)
        ? data.errors.map((e: FieldError) => e.message).join("\n")
        : data.message || data.error || `Erreur ${response.status}`;

    const error = new Error(message) as ApiError;
    error.status = response.status;
    if (data.errors) error.errors = data.errors;
    throw error;
};

export interface FieldError {
    field: string;
    message: string;
}

export interface ApiError extends Error {
    status?: number;
    errors?: FieldError[];
}

export const signIn = async (email: string, password: string) => {
    const response = await fetch(`${process.env.NEXT_PUBLIC_URL_API}/signin`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email, password }),
    });

    if (!response.ok) {
        const data = await response.json().catch(() => ({}));
        const error = new Error(data.message || data.error || `Erreur ${response.status}`) as Error & { status: number };
        error.status = response.status;
        throw error;
    }

    return await response.json();
}

export const signUp = async (lastName: string, firstName: string, email: string, gender: string, password: string) => {
    const response = await fetch(`${process.env.NEXT_PUBLIC_URL_API}/signup`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({ last_name: lastName, first_name: firstName, email, gender, password }),
    });

    if (!response.ok) {
        const data = await response.json().catch(() => ({}));
        const message = data.errors
            ? data.errors.map((e: { message: string }) => e.message).join('\n')
            : data.message || data.error || `Erreur ${response.status}`;
        const error = new Error(message) as Error & { status: number; errors?: { field: string; message: string }[] };
        error.status = response.status;
        if (data.errors) error.errors = data.errors;
        throw error;
    }

    return await response.json();
}

