@use "../../variables" as *;

// ── Page ──
.tracking-page {
  max-width: 448px;
  margin: 0 auto;
  padding: $spacing-6;
  padding-bottom: 8rem;
  position: relative;
}

.tracking-header {
  margin-bottom: $spacing-6;
}

.tracking-title {
  font-size: 1.5rem;
  font-weight: $font-semibold;
  color: $slate-900;
  margin: 0;
}

.tracking-date {
  font-size: $text-sm;
  color: $slate-400;
  margin: $spacing-1 0 0;
  text-transform: capitalize;
}

// ── Calorie Ring ──
.tracking-ring-section {
  display: flex;
  justify-content: center;
  margin-bottom: $spacing-6;
}

.calorie-ring {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;

  &__inner {
    position: absolute;
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  &__value {
    font-size: 1.75rem;
    font-weight: $font-semibold;
    color: $slate-900;
    line-height: 1;
  }

  &__label {
    font-size: 0.75rem;
    color: $slate-400;
    margin-top: 2px;
  }
}

// ── Macros Card ──
.tracking-macros-card {
  background: $white;
  border-radius: 1.25rem;
  border: 1px solid $slate-300;
  padding: $spacing-4 $spacing-5;
  display: flex;
  flex-direction: column;
  gap: $spacing-4;
  margin-bottom: $spacing-6;
}

.macro-bar {
  &__header {
    display: flex;
    align-items: center;
    gap: $spacing-2;
    margin-bottom: $spacing-1;
    color: $slate-600;
  }

  &__label {
    flex: 1;
    font-size: $text-sm;
    font-weight: $font-medium;
  }

  &__values {
    font-size: 0.75rem;
    color: $slate-400;
  }

  &__track {
    height: 6px;
    background: #f1f5f9;
    border-radius: 3px;
    overflow: hidden;
  }

  &__fill {
    height: 100%;
    border-radius: 3px;
    transition: width 0.4s ease;
  }
}

// ── Meals ──
.tracking-meals {
  display: flex;
  flex-direction: column;
  gap: $spacing-3;
}

.tracking-section-title {
  font-size: 1rem;
  font-weight: $font-semibold;
  color: $slate-900;
  margin: 0 0 $spacing-1;
}

.meal-card {
  background: $white;
  border-radius: 1.25rem;
  border: 1px solid $slate-300;
  overflow: hidden;

  &__header {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: $spacing-4;
    background: none;
    border: none;
    cursor: pointer;
    transition: background $transition-base;

    &:active {
      background: $gray-50;
    }
  }

  &__left {
    display: flex;
    align-items: center;
    gap: $spacing-3;
  }

  &__icon {
    width: 36px;
    height: 36px;
    border-radius: 0.625rem;
    background: $teal-50;
    color: $teal-600;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  &__slot {
    font-weight: $font-medium;
    color: $slate-900;
    font-size: 0.95rem;
  }

  &__cal {
    font-size: $text-sm;
    color: $slate-400;
    font-weight: $font-medium;
  }

  &__items {
    border-top: 1px solid #f1f5f9;
    padding: $spacing-2 $spacing-4 $spacing-4;
  }
}

.meal-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: $spacing-2 $spacing-1;

  &__name {
    font-size: $text-sm;
    color: $slate-600;
  }

  &__cal {
    font-size: 0.75rem;
    color: $slate-400;
  }
}

.meal-add-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: $spacing-1;
  width: 100%;
  padding: $spacing-2;
  margin-top: $spacing-2;
  border: 1px dashed $teal-600;
  border-radius: 0.75rem;
  background: $teal-50;
  color: $teal-600;
  font-size: $text-sm;
  font-weight: $font-medium;
  cursor: pointer;
  transition: all $transition-base;

  &:hover {
    background: darken($teal-50, 2%);
  }
}

// ══════════════════════════════════
// DESIGN B — Stacked Cards
// ══════════════════════════════════

.stat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: $spacing-3;
  margin-bottom: $spacing-5;
}

.stat-card {
  background: $white;
  border-radius: 1rem;
  border: 1px solid $slate-300;
  border-left: 3px solid;
  padding: $spacing-3 $spacing-4;

  &__top {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: $spacing-1;
  }

  &__value {
    font-size: 1.25rem;
    font-weight: $font-semibold;
    color: $slate-900;
  }

  &__unit {
    font-size: 0.75rem;
    color: $slate-400;
  }

  &__label {
    display: block;
    font-size: $text-sm;
    font-weight: $font-medium;
    color: $slate-600;
  }

  &__remaining {
    display: block;
    font-size: 0.7rem;
    color: $slate-400;
    margin-top: 2px;
  }
}

// Day Picker
.day-picker {
  display: flex;
  justify-content: space-between;
  margin-bottom: $spacing-5;
  padding: 0 $spacing-1;

  &__btn {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    padding: $spacing-2;
    border: none;
    background: none;
    cursor: pointer;
    border-radius: 0.75rem;
    transition: all $transition-base;
    min-width: 40px;

    &.active {
      background: $teal-600;

      .day-picker__label,
      .day-picker__date {
        color: $white;
      }
    }
  }

  &__label {
    font-size: 0.7rem;
    color: $slate-400;
    font-weight: $font-medium;
    text-transform: uppercase;
  }

  &__date {
    font-size: 0.9rem;
    font-weight: $font-semibold;
    color: $slate-900;
  }
}

// Food Log
.food-log {
  display: flex;
  flex-direction: column;
  gap: $spacing-4;

  &__group {
    display: flex;
    flex-direction: column;
    gap: $spacing-2;
  }

  &__time {
    font-size: 0.75rem;
    font-weight: $font-semibold;
    color: $slate-400;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding-left: $spacing-1;
  }

  &__item {
    background: $white;
    border: 1px solid $slate-300;
    border-radius: 1rem;
    padding: $spacing-3 $spacing-4;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  &__info {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }

  &__name {
    font-size: 0.9rem;
    font-weight: $font-medium;
    color: $slate-900;
  }

  &__macros {
    font-size: 0.7rem;
    color: $slate-400;
  }

  &__cal {
    font-size: $text-sm;
    color: $slate-400;
    font-weight: $font-medium;
    white-space: nowrap;
  }
}

// ══════════════════════════════════
// DESIGN C — Progress Stack
// ══════════════════════════════════

.hero-summary-card {
  background: $white;
  border-radius: 1.5rem;
  border: 1px solid $slate-300;
  padding: $spacing-5;
  margin-bottom: $spacing-6;
  box-shadow: 0 20px 40px -12px rgba(13, 148, 136, 0.08);
}

// Semi-circle gauge
.semi-gauge {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  margin-bottom: $spacing-4;

  &__info {
    position: absolute;
    top: 55px;
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  &__value {
    font-size: 2rem;
    font-weight: $font-semibold;
    color: $slate-900;
    line-height: 1;
  }

  &__unit {
    font-size: 0.75rem;
    color: $slate-400;
  }

  &__footer {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: $spacing-6;
    margin-top: -$spacing-2;
  }

  &__stat {
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  &__stat-value {
    font-size: 1rem;
    font-weight: $font-semibold;
    color: $slate-900;
  }

  &__stat-label {
    font-size: 0.7rem;
    color: $slate-400;
  }

  &__divider {
    width: 1px;
    height: 28px;
    background: $slate-300;
  }
}

// Macro pills in hero
.macro-pills {
  display: flex;
  gap: $spacing-3;
  margin-top: $spacing-4;
  padding-top: $spacing-4;
  border-top: 1px solid #f1f5f9;
}

.macro-pill {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;

  &__header {
    display: flex;
    align-items: center;
    gap: 4px;
  }

  &__label {
    font-size: 0.65rem;
    color: $slate-400;
    font-weight: $font-medium;
    text-transform: uppercase;
  }

  &__bar {
    height: 4px;
    background: #f1f5f9;
    border-radius: 2px;
    overflow: hidden;
  }

  &__fill {
    height: 100%;
    border-radius: 2px;
    transition: width 0.4s ease;
  }

  &__value {
    font-size: 0.7rem;
    color: $slate-600;
    font-weight: $font-medium;
  }
}

// Meal accordions
.meal-accordion {
  background: $white;
  border-radius: 1.25rem;
  border: 1px solid $slate-300;
  overflow: hidden;

  &__header {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: $spacing-4;
    background: none;
    border: none;
    cursor: pointer;
    transition: background $transition-base;

    &:active {
      background: $gray-50;
    }
  }

  &__info {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
  }

  &__count {
    font-size: 0.7rem;
    color: $slate-400;
  }

  &__right {
    display: flex;
    align-items: center;
    gap: $spacing-2;
  }

  &__chevron {
    color: $slate-300;
    transition: transform 0.2s ease;

    &.rotated {
      transform: rotate(180deg);
    }
  }

  &__body {
    border-top: 1px solid #f1f5f9;
    padding: $spacing-2 $spacing-4 $spacing-4;
  }

  &__item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: $spacing-2 $spacing-1;
  }

  &__item-info {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }
}

// Sticky bottom macro bar
.sticky-macro-bar {
  position: fixed;
  bottom: 5.5rem;
  left: 50%;
  transform: translateX(-50%);
  max-width: 400px;
  width: calc(100% - 3rem);
  background: $white;
  border: 1px solid $slate-300;
  border-radius: 999px;
  padding: $spacing-2 $spacing-4;
  display: flex;
  justify-content: space-around;
  align-items: center;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
  z-index: 50;

  &__item {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 0.75rem;
    font-weight: $font-medium;
    color: $slate-600;

    &--cal {
      font-weight: $font-semibold;
      color: $slate-900;
    }
  }

  &__dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
  }
}

